const labelsDocumentBasePending=labels102;
const standardsBasePending=standardsPage9;
standardsPage9=function(){const html=standardsBasePending();const dom=document.createElement('template');dom.innerHTML=html;
 const rows=[...dom.content.querySelectorAll('tr')];let group='';for(const row of rows){const code=row.querySelector('small')?.textContent||'';if(!code.includes('.'))continue;const g=code.split('.')[0];if(g!==group){group=g;const divider=document.createElement('tr');divider.className='indicator-divider-pending';divider.innerHTML=`<th colspan="2">${({work:T('Kondisi pekerjaan','Work conditions'),access:T('Akses label','Label access'),activity:T('Aktivitas label','Label activity')})[g]||E(g)}</th>`;row.before(divider);}}
 return dom.innerHTML;};
labels102=function(){const html=labelsDocumentBasePending();if(isLabel10())return html;return html+ten.members.filter(m=>m.documentRequest?.status==='pending').map(m=>`<section class="panel pad"><div class="approval-row-ui"><div><strong>${E(m.name)}</strong><p>${T('Penggantian KTP penanggung jawab','Representative identity document replacement')}</p></div>${pb(T('Periksa','Review'),'document-review',m.id)}</div></section>`).join('');};labelsPage9=labels102;
function reviewDocumentPending(id){if(isLabel10())return;const m=RM10.getMember(ten,id),q=m.documentRequest;if(q?.status!=='pending')return;reviewDialogUI(T('Pemeriksaan dokumen identitas','Identity document review'),`${reviewHeadingUI(m,'pending')}${identityRead10({...m.identity,documentImage:q.image})}<form data-pending-document-review="${m.id}" data-id="${q.id}" class="review-decision-ui"><label>${T('Catatan perbaikan','Correction note')}<textarea name="note" rows="2"></textarea></label><footer class="review-footer-ui"><button class="btn" name="decision" value="correct">${T('Minta perbaikan','Request corrections')}</button><button class="btn primary" name="decision" value="approve">${T('Setujui dokumen','Approve document')}</button></footer></form>`);}
window.addEventListener('click',e=>{const b=e.target.closest('[data-pending=document-review]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();reviewDocumentPending(b.dataset.id);},true);
window.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.pendingDocumentReview)return;e.preventDefault();e.stopImmediatePropagation();try{RM10.act(ten,e.submitter.value==='approve'?'document_approve':'document_correct',{member:f.dataset.pendingDocumentReview,id:f.dataset.id,note:f.elements.note.value});save10();closeModal();render();}catch(err){toast(error10(err.message));}},true);
const errorRefreshBasePending=error10;
error10=function(code){if(code==='identity_changed'){const f=document.querySelector('[data-ten-form=bank_correct]');if(f&&!f.querySelector('[data-ten=bank]'))f.insertAdjacentHTML('afterbegin',`<div class="full payout-correction-ui">${T('Identitas label telah diperbarui. Periksa kembali sebelum menyetujui rekening.','Label identity has changed. Review it again before approval.')} ${b10(T('Periksa kembali','Review again'),'bank',f.dataset.id)}</div>`);}return errorRefreshBasePending(code);};
const notificationsActionBasePending=handleAction;
handleAction=async function(b){const opening=b.dataset.action==='notifications'&&!(v5.pop==='notifications'&&document.querySelector('#header-popover'));const result=await notificationsActionBasePending(b);if(opening&&ten.role==='super'){const box=document.querySelector('#header-popover .popover-body')||document.querySelector('#header-popover');if(box){const news=ten.notifications.filter(n=>n.role==='super'&&n.key==='bonus_claimed').slice(0,6);box.insertAdjacentHTML('beforeend',news.map(n=>{const m=RM10.getMember(ten,n.member),bonus=ten.bonuses.find(b=>b.id===n.ref);return `<div class="approval-row-ui"><div><strong>${E(m?.name||'Label')}</strong><p>${T('Bonus diklaim','Bonus claimed')+' · '+bonus?.amount+' '+T('kredit','credits')}</p><small>${date10(n.at,true)}</small></div>${pb('↗','monitor-open')}</div>`;}).join(''));}}return result;};
// Keep sensitive review work available on the label profile without adding a new menu.
const identityDetailsDocumentBase=identityDetails102;
identityDetails102=function(m){return identityDetailsDocumentBase(m)+(isLabel10()?`<div class="ten-actions">${b10(T('Atur foto identitas','Adjust identity image'),'document')}</div>${m.documentRequest?.status==='pending'?`<p>${T('Dokumen pengganti sedang diperiksa.','The replacement document is under review.')}</p>`:m.documentRequest?.status==='correction'?`<p class="payout-correction-ui">${E(m.documentRequest.note)}</p>`:''}`:'');};
const rewardRenderBasePending=render;
render=function(){rewardRenderBasePending();if(!isLabel10()||state.page!=='dashboard')return;const member=ten.member;setTimeout(()=>{if(!isLabel10()||ten.member!==member||state.page!=='dashboard'||document.querySelector('#dialog').open)return;ten.rewardPromptsShown??=[];const bonus=ten.bonuses.find(b=>b.member===member&&RM10.pending.status(ten,b)==='pending'&&!ten.rewardPromptsShown.includes(b.id));if(!bonus)return;ten.rewardPromptsShown.push(bonus.id);save10();bonusPopup(bonus.id);},0);};
render();
